                const q = new URLSearchParams(raw), oid = q.get('platform_order_id') || '', o = orders[oid], go = (ok) => { res.statusCode = 302; res.setHeader('Location', (SITE_URL || '') + '/?pay=' + (ok ? 'ok' : 'cancel')); res.end(); };
                if (!o || o.prov !== 'shopier' || !SH.sec) return go(false);
                const rnd = q.get('random_nr') || '', sig = q.get('signature') || '', exp = crypto.createHmac('sha256', SH.sec).update(rnd + oid).digest('base64');
