// service worker: index'i önbellekte tutar → ikinci açılış anında; arka planda ETag ile sürüm denetler, yeni sürümde sayfaya haber verir
const SW_JS = `const C='aw-v2';
self.addEventListener('install',e=>{self.skipWaiting();});
self.addEventListener('activate',e=>{e.waitUntil(self.clients.claim());});
self.addEventListener('fetch',e=>{const r=e.request,u=new URL(r.url);
 if(r.method!=='GET'||u.origin!==location.origin)return;
 if(r.mode==='navigate'||u.pathname==='/'||u.pathname==='/index.html'){
  e.respondWith((async()=>{const c=await caches.open(C),hit=await c.match('/');
   const net=fetch('/',{cache:'no-cache'}).then(async n=>{if(n.ok){const old=hit&&hit.headers.get('ETag');await c.put('/',n.clone());
     if(old&&old!==n.headers.get('ETag')){(await self.clients.matchAll()).forEach(w=>w.postMessage({t:'aw-update'}));}}return n;}).catch(()=>null);
   if(hit){e.waitUntil(net);return hit;} return (await net)||new Response('Çevrimdışı / Offline',{status:503});})());
  return;}
 if(u.pathname.startsWith('/a/')||u.pathname.startsWith('/music/')||/\\.(png|webmanifest)$/.test(u.pathname))e.respondWith(caches.open(C).then(c=>c.match(r).then(h=>h||fetch(r).then(n=>{if(n.ok)c.put(r,n.clone());return n;}))));
});
self.addEventListener('push',e=>{let d={};try{d=e.data.json();}catch(x){}e.waitUntil(self.registration.showNotification(d.title||'${SITE_NAME}',{body:d.body||'',icon:'/icon-192.png',badge:'/icon-192.png',tag:d.tag||'aw',data:d}));});
self.addEventListener('notificationclick',e=>{e.notification.close();e.waitUntil(self.clients.matchAll({type:'window'}).then(L=>L.length?L[0].focus():self.clients.openWindow('/')));});`;
app.get('/sw.js', (req, res) => { res.setHeader('Service-Worker-Allowed', '/'); sendText(res, 'application/javascript', SW_JS, 'no-cache'); });
