function slamGive(u, f) { const R = slamReward(f); Object.keys(R.res).forEach(k => u[k] = (u[k] || 0) + R.res[k]); if (Object.keys(R.items).length) giveItems(u, R.items); const s = slamOf(u); s.coins = (s.coins || 0) + R.coins; return R; }
