function skinsOf(u) { const k = u.skins = u.skins && typeof u.skins === 'object' ? u.skins : { own: [], on: null }; k.own = Array.isArray(k.own) ? k.own.filter(x => SKINS[x]) : []; if (k.on && !k.own.includes(k.on)) k.on = null; return k; }
