function bSide(name, ch, r, atk, extra) { return Object.assign({ name, ch: ch || null, n: (atk ? r.atkN : r.defN) || 0, lost: (atk ? r.attackerLosses : r.defenderLosses) || 0, pow: (atk ? r.atkPower : r.defPower) || 0 }, extra || {}); }
