    const o = orders[oid]; if (!o || o.st === 'paid') return false; const u = users[o.u], P0 = PRODUCTS[o.pid]; if (!u || !P0) { o.st = 'orphan'; saveOrders(); return false; }
    o.st = 'paid'; o.paidAt = Date.now(); o.src = src || o.prov; u.buys = u.buys || {};
    const first = P0.first && !u.buys[o.pid], g = (P0.gold || 0) * (first ? 2 : 1); u.buys[o.pid] = (u.buys[o.pid] || 0) + 1;
    o.g = g; if (g) u.gold = (u.gold || 0) + g; if (P0.items) giveItems(u, P0.items);
