    GATES.forEach((g, i) => out.push({ id: 'gate' + i, k: 'gate', l: wallLvl, x: g[0], z: g[1], r: ROLE.gate.r, hp: Math.round(700 * (1 + 0.6 * wallLvl) * ROLE.gate.h), rng: 0, dps: 0, gate: true, def: true }));
