    if (!inZone(+c.x, +c.z) && !(c.a === 's')) return false;
    if (c.a === 'd') { const k = String(c.k), n = Math.floor(+c.n); const U = setup.U[k]; if (!U || !(n > 0) || !((st.left[k] || 0) >= n) || st.dep >= 40) return false;
      st.left[k] -= n; st.dep++; const s = squad(st, 'A', k, n, U, +c.x, +c.z); st.s.push(s); st.ev.push({ e: 'dep', id: s.id }); return true; }
    if (c.a === 's') { const S = SPELL[c.s]; if (!S || !((st.sp[c.s] || 0) > 0) || Math.abs(+c.x) > EDGE || Math.abs(+c.z) > EDGE) return false; st.sp[c.s]--; st.fx.push({ s: c.s, x: +c.x, z: +c.z, r: S.r, left: S.dur }); st.ev.push({ e: 'spell', s: c.s, x: +c.x, z: +c.z }); return true; }
