// raidsrv.js — v10 Canlı Baskın sunucu yardımcıları (raid10.py bot.js'e gömer; TROOPS/TIER/upgradeCost/bLevel/protectedAmount/bullyMult bot.js'ten gelir)
//   kapasite: CoC "ordu kampı" gibi — baskına götürülen asker "yer" tutar: yer(T) = mult^0,8 (yüksek kademe yer başına biraz daha güçlü)
const RAID = { cap: L => 150 + 60 * L, gcap: L => 40 + 20 * L, npcDay: 8, life: 6 * 60e3, cups: [8, 14, 20], npcCups: [3, 5, 8] };
function raidSpace(key) { return Math.pow(TIER.mult[+key.slice(1) - 1] || 1, 0.8); }
function raidUnits() { const U = {}; for (const k of TROOP_KEYS) { const T = TROOPS[k[0]], m = TIER.mult[+k.slice(1) - 1]; U[k] = { hp: Math.round((T.hp + T.def * 0.5) * m * 10) / 10, atk: Math.round(T.atk * m * 0.5 * 100) / 100, sp: Math.round(raidSpace(k) * 100) / 100 }; } return U; }
// ordudan kapasite kadar seç: bileşim korunur (her türden orantılı), artan yer yüksek kademeyle dolar
function raidPick(troops, cap) { const keys = Object.keys(troops || {}).filter(k => troops[k] > 0).sort((a, b) => (+b.slice(1) - +a.slice(1)) || (a < b ? -1 : 1)), out = {};
    const tot = keys.reduce((a, k) => a + troops[k] * raidSpace(k), 0), f = tot > cap ? cap / tot : 1; let room = cap;
    for (const k of keys) { const n = Math.floor(troops[k] * f); if (n > 0) { out[k] = n; room -= n * raidSpace(k); } }
    for (const k of keys) { const sp = raidSpace(k), n = Math.min(troops[k] - (out[k] || 0), Math.floor(room / sp)); if (n > 0) { out[k] = (out[k] || 0) + n; room -= n * sp; } }
    return out; }
function raidGarrison(troops, cap) { const p = raidPick(troops, cap), top = Object.entries(p).sort((a, b) => b[1] * raidSpace(b[0]) - a[1] * raidSpace(a[0])).slice(0, 3); return top.map(([k, n]) => ({ k, n })); }
// NPC çete karargâhı: seviye L, tohum s (ad ve yerleşim çeşitliliği)
const NPC_NAMES = [['Liman Çetesi', 'Harbour Gang'], ['Kara Eldiven', 'Black Glove'], ['Kemik Kırıcılar', 'Bonebreakers'], ['Gece Kuşları', 'Night Owls'], ['Pas Kardeşler', 'Rust Brothers'], ['Kızıl Tilki', 'Red Fox Crew'], ['Demir Yaka', 'Iron Collar'], ['Sis Ailesi', 'Fog Family']];
function npcBase(L, s) {
    const kinds = ['camp', 'ammu', 'vault', 'cargo', 'counterfeiter', 'invest', 'diner', 'smelter', 'cargo', 'counterfeiter', 'hospital', 'ammu', 'cargo', 'counterfeiter', 'ammu'];
    const nA = Math.min(3, 1 + Math.floor(L / 8)), n = Math.min(kinds.length, 7 + Math.floor(L / 3)), b = [{ id: 'mansion', kind: 'mansion', level: L }]; let a = 0;
    for (let i = 0; i < n; i++) { const k = kinds[i]; if (k === 'ammu' && ++a > nA) continue; b.push({ id: k + '_' + i, kind: k, level: Math.max(1, L - ((i + s) % 3)) }); }
    const tl = Math.min(8, 1 + Math.floor(L / 4)), g = [{ k: 'k' + tl, n: Math.round((30 + 10 * L) / raidSpace('k' + tl)) }, { k: 't' + tl, n: Math.round((20 + 8 * L) / raidSpace('t' + tl)) }];
    const f = 0.22 * Math.pow(1.5, Math.min(L, 30)), loot = { cash: Math.floor(5000 * f), cargo: Math.floor(5000 * f), arms: Math.floor(1500 * f), metal: Math.floor(1500 * f) };
    return { name: NPC_NAMES[s % NPC_NAMES.length], lvl: L, b, g, wall: Math.max(1, L - 2), loot };
}

/*RAIDSIM-END*/

// ═══ v10 CANLI BASKIN — CoC tarzı anlık savaş (deterministik: istemci canlı oynatır, sunucu aynı simülasyonla doğrular) ═══
const raids = Object.create(null); let raidTop = { t: 0, d: [] };
function raidLvl(u) { return (u.base && u.base.level) || 1; }
// ── v13 YILDIZ SANDIĞI: her Canlı Baskın'da kazanılan ★ sandığa dolar (SC_NEED ★ = sandık hazır); açılınca ödül — oynadıkça bir sonraki ödüle koşma döngüsü ──
const SC_NEED = 10;
function starChest(u) { if (!u.sc || typeof u.sc !== 'object') u.sc = { n: 0, opened: 0 }; return u.sc; }
function starChestRoll(u) { const lv = raidLvl(u), big = Math.random() < 0.15, k = (big ? 2.2 : 1) * (0.85 + Math.random() * 0.4);
    return { cash: Math.round((18000 + lv * 7000) * k / 100) * 100, cargo: Math.round((14000 + lv * 5500) * k / 100) * 100, arms: Math.round((5000 + lv * 2200) * k / 100) * 100, gold: big ? 150 : 25 + Math.floor(Math.random() * 3) * 15, big }; }
function raidCanTarget(u, t) { return t && t !== u && t.base && t.username !== 'admin' && !t.banned && !t.deleted && !(u.clan && t.clan === u.clan) && !((t.shieldUntil || 0) > Date.now()) && !(((u.rhist || {})[t.username] || 0) > Date.now() - 3 * 3600e3); }
const PWC = new WeakMap(); // güç önbelleği (60 sn) — binlerce oyuncuda rakip aramak ucuz kalsın
function powCached(t) { const c = PWC.get(t); if (c && Date.now() - c.t < 60000) return c.v; const v = calculatePlayerPower(t); PWC.set(t, { t: Date.now(), v }); return v; }
const DET = process.env.AW_DET === '1' && process.env.NODE_ENV !== 'production'; // yalnız test: belirlenimli baskın hedefi (ekran görüntüsü A/B adaleti)
function raidFindFoe(u) {
    const ap = Math.max(1, calculatePlayerPower(u)), pool = [];
    for (const un in users) { const t = users[un]; if (!raidCanTarget(u, t)) continue; const r = powCached(t) / ap; if (r >= 0.55 && r <= 1.7 && Math.abs(raidLvl(t) - raidLvl(u)) <= 4) pool.push(t); if (pool.length > 400) break; }
    return pool.length ? (DET ? pool.sort((a, b) => (a.username > b.username) - (a.username < b.username))[0] : pool[Math.floor(Math.random() * pool.length)]) : null;
}
function raidLootOf(u, t) { const prot = protectedAmount(t), rate = Math.min(0.5, 0.2 + invBonus(u, 'plunder') + lb(u, 'plunder')) * bullyMult(u, t), L = {}; for (const r of ['cash', 'cargo', 'arms', 'metal']) L[r] = Math.floor(Math.max(0, (t[r] || 0) - prot) * rate); return L; }
function raidSetupFor(u, forced) {
    syncTroops(u); const L = raidLvl(u), army = raidPick(u.troops, RAID.cap(L)); if (!Object.keys(army).length) return null;
    const t = forced || ((DET || Math.random() < 0.85) ? raidFindFoe(u) : null); let foe, b, g, loot, wall;
    if (t) { syncTroops(t); wall = bLevel(t, 'wall_main') || 1; b = (t.buildings || []).map(x => ({ id: x.id, kind: x.kind, level: x.level })).concat([{ id: 'mansion', kind: 'mansion', level: raidLvl(t) }]);
        g = raidGarrison(t.troops, RAID.gcap(raidLvl(t))); loot = raidLootOf(u, t); foe = { name: t.username, lvl: raidLvl(t), pow: calculatePlayerPower(t), cups: t.cups || 0, npc: false, ch: t.character || 'soulreaper' }; }
    else { const dl = Math.max(1, Math.min(30, L + Math.floor(Math.random() * 3) - 1)), sd = Math.floor(Math.random() * 1000), N = npcBase(dl, sd); wall = N.wall; b = N.b; g = N.g; loot = N.loot;
        const rd = raidDay(u); if (rd.npc >= RAID.npcDay) for (const r in loot) loot[r] = Math.floor(loot[r] * 0.25);
        foe = { name: N.name, lvl: dl, pow: 0, npc: true, ch: '@npc' }; }
    const keys = new Set(Object.keys(army).concat(g.map(x => x.k))), UA = raidUnits(), U = {}; keys.forEach(k => U[k] = UA[k]);
    const setup = { b: RaidSim.layout(b, wall), g, U, spells: { molo: 1 + Math.floor(L / 10), rage: 1 }, army, alvl: L, loot };
    return { rid: 'r' + Date.now().toString(36) + crypto.randomBytes(3).toString('hex'), setup, foe, t0: Date.now(), start: 0, cmds: [], last: -1 };
}
function raidDay(u) { const d = dayKey(Date.now()); if (!u.rday || u.rday.d !== d) u.rday = { d, npc: 0, n: 0 }; return u.rday; }
function raidCupsFor(R, res) { const C = R.foe.npc ? RAID.npcCups : RAID.cups; return res.stars ? C[res.stars - 1] : (R.foe.npc ? 0 : -5); }
function raidFinish(un, why) {
    const R = raids[un]; if (!R) return null; delete raids[un]; const u = users[un]; if (!u || !R.cmds.length) return null;
    syncTroops(u); const army = {}; for (const k in R.setup.army) army[k] = Math.min(R.setup.army[k], u.troops[k] || 0); const S0 = Object.assign({}, R.setup, { army });
    const t = R.foe.npc ? null : users[R.foe.name];
    if (t) { const cur = raidLootOf(u, t); for (const r in S0.loot) S0.loot[r] = Math.min(S0.loot[r], cur[r]); }
    const res = RaidSim.run(S0, R.cmds);
    mixAdd(u.troops, res.dead, -1); const hosp = mixTotal(res.dead) ? sendToHospital(u, res.dead) : { admitted: 0, dead: 0 }; syncTroops(u);
    for (const r in res.loot) u[r] = (u[r] || 0) + res.loot[r];
    const dc = raidCupsFor(R, res); u.cups = Math.max(0, (u.cups || 0) + dc); const rd = raidDay(u); rd.n++; if (R.foe.npc) rd.npc++;
    u.rhist = u.rhist || {}; if (t) u.rhist[t.username] = Date.now(); for (const k in u.rhist) if (u.rhist[k] < Date.now() - 6 * 3600e3) delete u.rhist[k];
    const rep = { t: Date.now(), foe: R.foe, att: { name: un, lvl: raidLvl(u), ch: u.character || 'soulreaper' }, setup: S0, cmds: R.cmds, res: { stars: res.stars, pct: res.pct, loot: res.loot } };
    u.rlast = rep; stat(u, 'raids'); questProgress(u, 'attack', 1); statInc('raid', R.foe.npc ? 'npc' : 'pvp');
    if (t) { for (const r in res.loot) t[r] = Math.max(0, (t[r] || 0) - res.loot[r]); syncTroops(t); const gd = {}; for (const k in res.gdead) gd[k] = Math.min(res.gdead[k], t.troops[k] || 0); mixAdd(t.troops, gd, -1); if (mixTotal(gd)) sendToHospital(t, gd); syncTroops(t);
        t.cups = Math.max(0, (t.cups || 0) - dc); if (res.stars) t.shieldUntil = Math.max(t.shieldUntil || 0, Date.now() + RAID_SHIELD);
        t.rdef = [rep].concat(t.rdef || []).slice(0, 5); pushOff(t, 'raided', { n: un }); if (res.stars >= 3 && raidLvl(t) >= 8) news('raid', [un, t.username]);
        marchReport(t, 'Canlı Baskın', `${un} üssüne baskın yaptı: ${'★'.repeat(res.stars) || 'yıldız yok'} · yıkım %${res.pct} · kayıp ${costText(res.loot)}. Kaydı Savaş → Canlı Baskın bölümünden izleyebilirsin.`);
        emitTo(t.username, 'toast', { type: 'defeat', msg: `${un} canlı baskınla saldırdı: ${'★'.repeat(res.stars) || '0 ★'} · %${res.pct}` }); pushResources(t.username); }
    try { LIV.onRaid(un, t, res, R); } catch (e) { console.error('[LIV.onRaid]', e.message); }
    markDirty('users'); pushResources(un); emitTo(un, 'profileData', publicPlayer(u));
    const SCh = starChest(u), sc0 = SCh.n; if (!u.ai) SCh.n = Math.min(SC_NEED, SCh.n + res.stars);
    const out = { stars: res.stars, pct: res.pct, loot: res.loot, dead: hosp.dead, wounded: hosp.admitted, cups: dc, total: u.cups, foe: R.foe, why: why || '', sc: { n0: sc0, n: SCh.n, need: SC_NEED } };
    emitTo(un, 'raidResult', out); return out;
}
setInterval(() => { const now = Date.now(); for (const un in raids) { const R = raids[un];
    if (R.start && now - R.start > (RaidSim.TMAX / 10 + 20) * 1000) raidFinish(un, 'time');
    else if (!R.start && now - R.t0 > RAID.life) delete raids[un]; } }, 5000);
function raidTopList() { if (Date.now() - raidTop.t < 30000) return raidTop.d; const L = []; for (const un in users) { const u = users[un]; if (u.cups > 0 && un !== 'admin' && !u.banned) L.push({ name: un, cups: u.cups, lvl: raidLvl(u), clan: u.clan && clans[u.clan] ? clans[u.clan].name : null }); }
    L.sort((a, b) => b.cups - a.cups); raidTop = { t: Date.now(), d: L.slice(0, 30) }; return raidTop.d; }

// ═══ v10 VURGUN: Paylaş ya da Çal ═══
const HEIST = { day: 6, go: 9000, choose: 15000, fill: 7000, size: 4, tap: 0.05, taps: 3 }; // go: kasa kırma (her açılan kilit ganimete +%5, kişi başı 3)
const HNPC = { bruno: { p: 0.92 }, enzo: { p: 0.5 }, lorenzo: { p: 0.5 }, nina: { tft: 1 }, paolo: { trust: 45 }, sofia: { p: 0.4 }, gino: { p: 0.75 }, mikhail: { p: 0.8, rat: 1 } };
const HNAME = { bruno: 'Boğucu Bruno', enzo: 'Şoför Enzo', lorenzo: 'Kumarbaz Lorenzo', nina: 'Hacker Nina', paolo: 'Muhasebeci Paolo', sofia: 'Kara Kedi Sofia', gino: 'Bombacı Gino', mikhail: 'Silah Tüccarı Mikhail' };
let hq = []; const hrooms = Object.create(null), hfeed = []; let hseq = 0;
function trustOf(T) { T = T || { s: 0, t: 0 }; return Math.round(100 * (T.s + 1) / (T.s + T.t + 2)); }
function heistDay(u) { const d = dayKey(Date.now()); if (!u.hday || u.hday.d !== d) u.hday = { d, n: 0 }; return u.hday; }
function hnpcTrust(id) { stats.hnpc = stats.hnpc || {}; return trustOf(stats.hnpc[id]); }
function hMember(x) { if (x.npc) return { name: x.npc, npc: true, trust: hnpcTrust(x.npc), ch: x.npc }; const u = users[x.un]; return { name: x.un, npc: false, trust: trustOf(u && u.trust), ch: (u && u.character) || 'soulreaper', rat: !!(u && (u.rat || 0) > Date.now()), lvl: (u && u.base && u.base.level) || 1 }; }
function heistView(R, un) { return { id: R.id, phase: R.phase, ends: R.ends, pot: R.pot, taps: R.taps, bonus: Math.round(R.bonus * 100), members: R.m.map(hMember), mine: R.ch[un] || null, locked: R.m.filter(x => !x.npc && R.ch[x.un]).map(x => x.un), out: R.out || null }; }
function heistEmit(R) { for (const x of R.m) if (!x.npc) emitTo(x.un, 'heistRoom', heistView(R, x.un)); }
function heistPot(R) { const hs = R.m.filter(x => !x.npc).map(x => users[x.un]).filter(Boolean), L = hs.length ? hs.reduce((a, u) => a + ((u.base && u.base.level) || 1), 0) / hs.length : 1, f = 0.07 * Math.pow(1.5, Math.min(30, L)), n = R.m.length;
    return { cash: Math.floor(5000 * f * n), cargo: Math.floor(5000 * f * n), arms: Math.floor(1500 * f * n), gold: 4 * n }; }
function heistStart(list) {
    const R = { id: 'h' + (++hseq) + Date.now().toString(36), m: list.map(un => ({ un })), ch: Object.create(null), phase: 'go', t0: Date.now() };
    const pool = Object.keys(HNPC).sort(() => Math.random() - 0.5); while (R.m.length < Math.max(2, Math.min(HEIST.size, list.length < 2 ? 3 + (Math.random() < 0.5 ? 1 : 0) : list.length))) R.m.push({ npc: pool.pop() });
    R.base = heistPot(R); R.pot = Object.assign({}, R.base); R.bonus = 0; R.taps = Object.create(null); R.tapT = Object.create(null); R.ends = Date.now() + HEIST.go;
    for (const x of R.m) if (x.npc) { const n = Math.floor(Math.random() * 3); for (let i = 0; i < n; i++) setTimeout(() => heistTap(R, x.npc), 1500 + Math.random() * (HEIST.go - 2500)); } hrooms[R.id] = R; for (const un of list) { const u = users[un]; if (u) u._hr = R.id; } heistEmit(R); // NPC'ler de kilit açar (0–2)
    setTimeout(() => { R.phase = 'choose'; R.ends = Date.now() + HEIST.choose; heistEmit(R); setTimeout(() => heistReveal(R), HEIST.choose + 200); }, HEIST.go);
}
function heistTap(R, key) { if (R.phase !== 'go' || (R.taps[key] || 0) >= HEIST.taps) return false; R.taps[key] = (R.taps[key] || 0) + 1; R.bonus += HEIST.tap;
    for (const r in R.base) R.pot[r] = Math.floor(R.base[r] * (1 + R.bonus)); heistEmit(R); return true; }
function heistNpc(R, id) {
    const P0 = HNPC[id], hs = R.m.filter(x => !x.npc).map(x => users[x.un]).filter(Boolean);
    if (P0.tft) { const last = hs.map(u => (u.hmem || {})[id]).filter(Boolean); return last.includes('t') ? 't' : 's'; }
    if (P0.trust) { const avg = hs.length ? hs.reduce((a, u) => a + trustOf(u.trust), 0) / hs.length : 50; return avg >= P0.trust ? 's' : 't'; }
    if (P0.rat && hs.some(u => (u.rat || 0) > Date.now())) return 't';
    return Math.random() < P0.p ? 's' : 't';
}
function heistReveal(R) {
    if (R.phase === 'reveal' || !hrooms[R.id]) return; R.phase = 'reveal';
    for (const x of R.m) { const k = x.npc || x.un; if (!R.ch[k]) R.ch[k] = x.npc ? heistNpc(R, x.npc) : 's'; }
    const keys = R.m.map(x => x.npc || x.un), thieves = keys.filter(k => R.ch[k] === 't'), n = keys.length, out = { choices: Object.assign({}, R.ch), get: {} };
    out.kind = thieves.length === 0 ? 'share' : thieves.length === 1 ? 'one' : 'police'; out.thief = thieves.length === 1 ? thieves[0] : null;
    for (const k of keys) { const g = {}; for (const r in R.pot) g[r] = out.kind === 'share' ? Math.floor(R.pot[r] * 1.2 / n) : out.kind === 'one' && k === out.thief ? R.pot[r] : 0; out.get[k] = g; }
    stats.hnpc = stats.hnpc || {};
    for (const x of R.m) { const k = x.npc || x.un, c = R.ch[k];
        if (x.npc) { const T = stats.hnpc[x.npc] = stats.hnpc[x.npc] || { s: 0, t: 0 }; T[c]++; continue; }
        const u = users[x.un]; if (!u) continue; u.trust = u.trust || { s: 0, t: 0 }; u.trust[c]++; heistDay(u).n++; u._hr = null; u.hmem = u.hmem || {};
        for (const y of R.m) if (y.npc) u.hmem[y.npc] = c; // NPC'ler bu ekipte ne yaptığını hatırlar (Nina kısasa kısas)
        const g = out.get[k]; for (const r in g) u[r] = (u[r] || 0) + g[r];
        if (out.kind === 'one' && k === out.thief) u.rat = Date.now() + 24 * 3600e3;
        if (out.kind === 'one' && k !== out.thief && !HNPC[out.thief]) { u.vend = u.vend || {}; u.vend[out.thief] = Date.now() + 24 * 3600e3; }
        stat(u, 'heists'); pushResources(x.un); emitTo(x.un, 'profileData', publicPlayer(u)); }
    statsDirty = true; markDirty('users'); R.out = out; heistEmit(R); try { LIV.onHeist(R, out); } catch (e) { }
    const hum = R.m.filter(x => !x.npc).length;
    if (out.kind === 'one' && !HNPC[out.thief] && hum >= 2) chatWorld(`🐀 ${out.thief} ekibini sattı ve vurgunun hepsini kaçırdı!`);
    hfeed.unshift({ t: Date.now(), kind: out.kind, thief: out.thief, n, names: keys.map(k => HNAME[k] || k) }); if (hfeed.length > 12) hfeed.pop();
    setTimeout(() => delete hrooms[R.id], 60000);
}
setInterval(() => { // eşleştirme: 2+ oyuncu → hemen; tek oyuncu HEIST.fill ms bekledi → NPC ortaklarla
    const now = Date.now(); hq = hq.filter(q => users[q.un] && isOnline(q.un)); if (!hq.length) return;
    hq.sort((a, b) => trustOf(users[a.un].trust) - trustOf(users[b.un].trust)); // benzer güvendekiler birlikte
    while (hq.length >= 2 && (hq.length >= HEIST.size || now - Math.min(...hq.map(q => q.t)) > 3000)) heistStart(hq.splice(0, Math.min(HEIST.size, hq.length)).map(q => q.un));
    if (hq.length === 1 && now - hq[0].t > HEIST.fill) heistStart([hq.shift().un]);
}, 1000);

