        const msg = cleanText(String(data.msg).replace(/[\u0000-\u0008\u000b-\u001f]/g, ' ').slice(0, 500));
        t.inbox = t.inbox || []; t.inbox.unshift({ from: u.username, msg, date: Date.now(), read: false }); pushOff(t, 'mail', { n: u.username }); try { LIV.botDM(u, t, msg); } catch (e) { }
